sealed interface Document {
    data class Text(val value: String) : Document
    data object Line : Document
    data object Softline : Document
    data object Hardline : Document
    data object BreakParent : Document
    data class Suffix(val value: String) : Document
    data class IfBreak(val broken: String, val flat: String) : Document
    data class Group(val id: Int, val child: Document) : Document
    data class Nest(val amount: Int, val child: Document) : Document
    data class Align(val child: Document) : Document
    data class Concat(val children: List<Document>) : Document
}
fun Document.forced(): Boolean = when (this) {
    Document.Hardline, Document.BreakParent -> true
    is Document.Concat -> children.any {
        it.forced()
    }
    is Document.Group -> child.forced()
    is Document.Nest -> child.forced()
    is Document.Align -> child.forced()
    else -> false
}
fun Document.groupCount(): Int = when (this) {
    is Document.Group -> 1 + child.groupCount()
    is Document.Nest -> child.groupCount()
    is Document.Align -> child.groupCount()
    is Document.Concat -> children.sumOf {
        it.groupCount()
    }
    else -> 0
}
fun text(value: String): Document = Document.Text(value)
fun concat(parts: List<Document>): Document {
    val result = mutableListOf<Document>()
    fun flatten(document: Document) {
        if (document is Document.Concat) for (child in document.children) flatten(child)
        else if (document is Document.Text) {
            if (document.value.isEmpty()) return
            val previous = result.lastOrNull()
            if (previous is Document.Text) result[result.lastIndex] = Document.Text(previous.value + document.value) else result.add(document)
        } else result.add(document)
    }
    for (part in parts) flatten(part)
    return if (result.isEmpty()) text("") else if (result.size == 1) result[0] else Document.Concat(result)
}
fun nest(n: Int, child: Document): Document = Document.Nest(n, child)
fun align(child: Document): Document = Document.Align(child)
fun line(): Document = Document.Line
fun softline(): Document = Document.Softline
fun hardline(): Document = Document.Hardline
fun suffix(value: String): Document = Document.Suffix(value)
fun breakParent(): Document = Document.BreakParent
fun ifBreak(broken: String, flat: String): Document = Document.IfBreak(broken, flat)
class DocBuilder {
    var next = 0
    fun group(child: Document): Document = Document.Group(next++, child)
}

class SourceError(val line: Int, val column: Int, val reason: String) : Exception(reason)
data class Comment(val text: String, val line: Int, val column: Int, val blank: Int, val lineComment: Boolean, var own: Boolean = false)
data class Token(val text: String, val kind: String, val line: Int, val column: Int, val blank: Int,
val leading: MutableList<Comment> = mutableListOf(), val trailing: MutableList<Comment> = mutableListOf())
data class Occurrence(val token: Boolean, val index: Int)
data class Lexed(val tokens: MutableList<Token> = mutableListOf(), val comments: MutableList<Comment> = mutableListOf(), val order: MutableList<Occurrence> = mutableListOf())
object Lexer {
    fun letter(c: Char): Boolean = c in 'A'..'Z' || c in 'a'..'z'
    fun digit(c: Char): Boolean = c in '0'..'9'
    fun trim(text: String): String = text.trimEnd(' ')
    fun lex(lines: List<String>): Lexed {
        val result = Lexed()
        var previous = 0
        for ((row, line) in lines.withIndex()) {
            var i = 0
            while (i < line.length) {
                if (line[i] == ' ') {
                    i++; continue
                }
                val start = i
                val lineNumber = row + 1
                val blank = maxOf(0, lineNumber - previous - 1)
                fun failure(reason: String): SourceError = SourceError(lineNumber, start + 1, reason)
                if (line.startsWith("//", i)) {
                    result.order.add(Occurrence(false, result.comments.size))
                    result.comments.add(Comment(trim(line.substring(i)), lineNumber, i + 1, blank, true)); previous = lineNumber; break
                }
                if (line.startsWith("/*", i)) {
                    val end = line.indexOf("*/", i + 2)
                    if (end < 0) throw failure("unterminated comment")
                    result.order.add(Occurrence(false, result.comments.size))
                    result.comments.add(Comment(line.substring(i, end + 2), lineNumber, i + 1, blank, false)); previous = lineNumber; i = end + 2; continue
                }
                val kind: String
                if (letter(line[i]) || line[i] == '_') {
                    i++
                    while (i < line.length && (letter(line[i]) || digit(line[i]) || line[i] == '_')) i++
                    kind = if (line.substring(start, i) in listOf("int", "float", "bool", "string", "void", "if", "else", "while", "for", "return", "break", "continue", "true", "false", "switch", "case", "default")) "keyword" else "identifier"
                } else if (digit(line[i])) {
                    i++; while (i < line.length && digit(line[i])) i++
                    if (i + 1 < line.length && line[i] == '.' && digit(line[i + 1])) {
                        i += 2; while (i < line.length && digit(line[i])) i++
                    }
                    kind = "number"
                } else if (line[i] == '"') {
                    i++
                    var closed = false
                    while (i < line.length) {
                        if (line[i] == '\\') i += 2
                        else if (line[i] == '"') {
                            i++; closed = true; break
                        } else i++
                    }
                    if (!closed) throw failure("unterminated string")
                    kind = "string"
                } else if (i + 1 < line.length && line.substring(i, i + 2) in listOf("<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%=")) {
                    i += 2; kind = "symbol"
                }
                else if (line[i] in "+-*/%<>=!()[]{},;.?:") {
                    i++; kind = "symbol"
                }
                else throw failure("unexpected character '${line[i]}'")
                result.order.add(Occurrence(true, result.tokens.size))
                result.tokens.add(Token(line.substring(start, i), kind, lineNumber, start + 1, blank)); previous = lineNumber
            }
        }
        result.tokens.add(Token("", "end", lines.size + 1, 1, 0))
        return result
    }
}

import java.io.File
data class Profile(val values: MutableMap<String, String> = mutableMapOf()) {
    fun yes(key: String): Boolean = values[key] == "yes"
    fun number(key: String): Int = values.getValue(key).toInt()
    val kr: Boolean get() = values["brace_style"] == "kr"
}
fun attach(lexed: Lexed): Pair<List<Token>, Int> {
    val tokens = lexed.tokens
    for ((k, entry) in lexed.order.withIndex()) {
        if (entry.token) continue
        val comment = lexed.comments[entry.index]
        val previous = lexed.order.take(k).lastOrNull {
            it.token
        }?.index
        val next = lexed.order.drop(k + 1).firstOrNull {
            it.token
        }?.index
        val following = lexed.order.getOrNull(k + 1)
        val nextLine = following?.let {
            if (it.token) tokens[it.index].line else lexed.comments[it.index].line
        }
        comment.own = comment.lineComment || nextLine == null || nextLine > comment.line
        val trailing = previous != null && tokens[previous].line == comment.line && (next == null || tokens[next].line > comment.line)
        if (trailing) tokens[previous!!].trailing.add(comment) else tokens[next ?: tokens.lastIndex].leading.add(comment)
    }
    return Pair(tokens, lexed.comments.size)
}
fun checkComments(items: List<SyntaxNode>, tokens: List<Token>) {
    val allowed = mutableSetOf(tokens.lastIndex)
    val tails = mutableSetOf<Int>()
    fun walk(node: SyntaxNode) {
        when (node.kind) {
            "block" -> {
                allowed.add(node.tokens[1]); node.children.forEach {
                    allowed.add(it.start)
                }
            }
            "switch" -> {
                allowed.add(node.tokens[4])
                for (clause in node.children.drop(1)) {
                    allowed.add(clause.tokens[0])
                    clause.children.drop(if (clause.kind == "case") 1 else 0).forEach {
                        allowed.add(it.start)
                    }
                }
            }
            "if" -> {
                if (node.children[1].kind != "block") allowed.add(node.children[1].start)
                if (node.children.size == 3 && node.children[2].kind !in listOf("block", "if")) allowed.add(node.children[2].start)
            }
            "while" -> if (node.children[1].kind != "block") allowed.add(node.children[1].start)
            "for" -> if (node.children[3].kind != "block") allowed.add(node.children[3].start)
            "params", "args", "initlist" -> {
                node.children.forEach {
                    allowed.add(it.start)
                }; node.trailing?.let {
                    tails.add(it)
                }
            }
        }
        node.children.forEach {
            walk(it)
        }
    }
    for (item in items) {
        allowed.add(item.start); walk(item)
    }
    for ((i, token) in tokens.withIndex()) for (comment in token.leading) {
        if (comment.own && i !in allowed || i in tails) throw SourceError(comment.line, comment.column, "comment not allowed here")
    }
}
class Construction(val tokens: List<Token>, val profile: Profile) {
    val originalTrailing = tokens.map {
        it.trailing.isNotEmpty()
    }
    val docs = DocBuilder()
    fun space(): Document = text(if (profile.yes("space_around_operators")) " " else "")
    fun keywordSpace(): Document = text(if (profile.yes("space_after_keyword")) " " else "")
    fun operatorLine(): Document = if (profile.yes("space_around_operators")) line() else softline()
    fun separator(blank: Int): Document = concat(List(1 + minOf(blank, profile.number("max_blank_lines"))) {
        hardline()
    })
    fun preblank(token: Int): Int = tokens[token].leading.firstOrNull()?.blank ?: tokens[token].blank
    fun comments(comments: List<Comment>, next: Int?): Document {
        val parts = mutableListOf<Document>()
        for ((i, comment) in comments.withIndex()) {
            parts.add(text(comment.text))
            val blank = comments.getOrNull(i + 1)?.blank ?: next
            if (blank != null) parts.add(if (comment.own) separator(blank) else text(" "))
        }
        return concat(parts)
    }
    fun trailing(token: Int): Document = if (tokens[token].trailing.isEmpty()) text("") else suffix(tokens[token].trailing.joinToString(" ") {
        it.text
    })
    fun tokenWith(token: Int, leading: List<Comment>): Document = concat(listOf(comments(leading, tokens[token].blank), text(tokens[token].text), trailing(token)))
    fun token(token: Int): Document = tokenWith(token, tokens[token].leading)
    fun group(child: Document): Document = docs.group(child)
    fun level(node: SyntaxNode): Int = when (node.kind) {
        "conditional" -> 0; "binary" -> Parser.precedence(tokens[node.tokens[0]].text); "unary" -> 7; else -> 8
    }
    fun open(node: SyntaxNode, required: Int): SyntaxNode {
        var current = node
        while (profile.yes("remove_parens") && current.kind == "paren" && level(current.children[0]) >= required && tokens[current.tokens[0]].leading.isEmpty() && tokens[current.tokens[1]].leading.isEmpty()) {
            val child = current.children[0]
            val left = tokens[current.tokens[0]]
            val right = tokens[current.tokens[1]]
            val first = left.trailing.toList()
            val last = right.trailing.toList()
            left.trailing.clear(); right.trailing.clear()
            tokens[child.start].trailing.addAll(0, first)
            tokens[child.end].trailing.addAll(last)
            current = child
        }
        return current
    }
    fun list(node: SyntaxNode): Document {
        val left = node.tokens.first()
        val right = node.tokens.last()
        if (node.children.isEmpty()) return concat(listOf(token(left), token(right)))
        val forced = (node.start until node.end).any {
            originalTrailing[it]
        }
        val inside = mutableListOf<Document>(softline())
        for ((i, child) in node.children.withIndex()) {
            if (i > 0) inside.addAll(listOf(token(node.tokens[i]), line()))
            inside.add(when (node.kind) {
                "params" -> parameter(child); "initlist" -> initializer(child); else -> expression(child, 0)
            })
        }
        if (node.kind == "initlist") {
            inside.add(ifBreak(",", "")); node.trailing?.let {
                inside.add(trailing(it))
            }
        }
        return group(concat(listOf(if (forced) breakParent() else text(""), token(left), nest(profile.number("indent"), concat(inside)), softline(), token(right))))
    }
    fun parameter(node: SyntaxNode): Document {
        val parts = mutableListOf(token(node.tokens[0]), text(" "), token(node.tokens[1]))
        for (dimension in node.children) parts.addAll(listOf(token(dimension.tokens[0]), token(dimension.tokens[1])))
        return concat(parts)
    }
    fun declaration(node: SyntaxNode): Document {
        val parts = mutableListOf(token(node.tokens[0]), text(" "), token(node.tokens[1]))
        var initial: SyntaxNode? = null
        for (child in node.children) {
            if (child.kind == "dimension") {
                parts.add(token(child.tokens[0])); child.children.firstOrNull()?.let {
                    parts.add(expression(it, 0))
                }; parts.add(token(child.tokens[1]))
            } else initial = child
        }
        for (t in node.tokens.drop(2)) {
            if (tokens[t].text == "=") parts.addAll(listOf(space(), token(t), space(), initializer(initial!!))) else parts.add(token(t))
        }
        return concat(parts)
    }
    fun initializer(node: SyntaxNode): Document = if (node.kind == "initlist") list(node) else expression(node, 0)
    fun closing(token: Int): Pair<List<Comment>, List<Comment>> {
        val comments = tokens[token].leading
        val split = comments.indexOfLast {
            it.own
        } + 1
        return Pair(comments.take(split), comments.drop(split))
    }
    fun block(node: SyntaxNode): Document {
        val close = node.tokens[1]
        val (h, g) = closing(close)
        if (node.children.isEmpty() && h.isEmpty()) return concat(listOf(token(node.tokens[0]), tokenWith(close, g)))
        val inside = mutableListOf<Document>(hardline())
        for ((i, child) in node.children.withIndex()) {
            if (i > 0) inside.add(separator(preblank(child.start))); inside.add(statement(child))
        }
        if (h.isNotEmpty()) {
            if (node.children.isNotEmpty()) inside.add(separator(h[0].blank)); inside.add(comments(h, null))
        }
        return concat(listOf(token(node.tokens[0]), nest(profile.number("indent"), concat(inside)), hardline(), tokenWith(close, g)))
    }
    fun body(node: SyntaxNode): Document {
        val separator = if (profile.kr) text(" ") else hardline()
        if (node.kind == "block") return concat(listOf(separator, block(node)))
        val document = statement(node)
        if (profile.yes("add_braces")) return concat(listOf(separator, text("{"), nest(profile.number("indent"), concat(listOf(hardline(), document))), hardline(), text("}")))
        return nest(profile.number("indent"), concat(listOf(hardline(), document)))
    }
    fun simple(node: SyntaxNode): Document = if (node.kind == "assign") concat(listOf(expression(node.children[0], 0), space(), token(node.tokens[0]), space(), expression(node.children[1], 0))) else expression(node.children[0], 0)
    fun clause(node: SyntaxNode): Document {
        val parts = mutableListOf(token(node.tokens[0]))
        val first = if (node.kind == "case") 1 else 0
        if (first == 1) parts.addAll(listOf(text(" "), expression(node.children[0], 0)))
        parts.add(token(node.tokens[1]))
        if (node.children.size > first) {
            val statements = mutableListOf<Document>(hardline())
            for ((i, child) in node.children.drop(first).withIndex()) {
                if (i > 0) statements.add(separator(preblank(child.start))); statements.add(statement(child))
            }
            parts.add(nest(profile.number("indent"), concat(statements)))
        }
        return concat(parts)
    }
    fun statement(node: SyntaxNode): Document {
        return when (node.kind) {
            "block" -> block(node)
            "decl" -> declaration(node)
            "statement" -> concat(listOf(simple(node.children[0]), token(node.tokens[0])))
            "break", "continue" -> concat(node.tokens.map {
                token(it)
            })
            "return" -> {
                val parts = mutableListOf(token(node.tokens[0])); node.children.firstOrNull()?.let {
                    parts.addAll(listOf(text(" "), expression(it, 0)))
                }; concat(parts + token(node.tokens[1]))
            }
            "while", "if" -> {
                val condition = expression(node.children[0], 0)
                val body = this.body(node.children[1])
                val parts = mutableListOf(token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), condition, token(node.tokens[2]), body)
                if (node.kind == "if" && node.children.size == 3) {
                    parts.add(if (profile.kr && (node.children[1].kind == "block" || profile.yes("add_braces"))) text(" ") else hardline())
                    parts.add(token(node.tokens[3]))
                    if (node.children[2].kind == "if") parts.addAll(listOf(text(" "), statement(node.children[2]))) else parts.add(this.body(node.children[2]))
                }
                concat(parts)
            }
            "for" -> {
                val inner = mutableListOf<Document>()
                val initial = node.children[0]
                if (initial.kind != "empty") inner.add(if (initial.kind == "decl") declaration(initial) else simple(initial))
                inner.add(token(node.tokens[2]))
                if (node.children[1].kind != "empty") inner.addAll(listOf(line(), expression(node.children[1], 0)))
                inner.add(token(node.tokens[3]))
                if (node.children[2].kind != "empty") inner.addAll(listOf(line(), simple(node.children[2])))
                val group = group(align(concat(inner)))
                val body = body(node.children[3])
                concat(listOf(token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), group, token(node.tokens[4]), body))
            }
            "switch" -> {
                val close = node.tokens[4]
                val (h, g) = closing(close)
                val condition = expression(node.children[0], 0)
                val parts = mutableListOf(token(node.tokens[0]), keywordSpace(), token(node.tokens[1]), condition, token(node.tokens[2]), if (profile.kr) text(" ") else hardline(), token(node.tokens[3]))
                if (node.children.size > 1 || h.isNotEmpty()) {
                    val inside = mutableListOf<Document>(hardline())
                    for ((i, child) in node.children.drop(1).withIndex()) {
                        if (i > 0) inside.add(separator(preblank(child.start))); inside.add(clause(child))
                    }
                    if (h.isNotEmpty()) {
                        if (node.children.size > 1) inside.add(separator(h[0].blank)); inside.add(comments(h, null))
                    }
                    parts.addAll(listOf(nest(if (profile.yes("indent_case_labels")) profile.number("indent") else 0, concat(inside)), hardline()))
                }
                concat(parts + tokenWith(close, g))
            }
            else -> error("invalid statement")
        }
    }
    fun function(node: SyntaxNode): Document {
        val parameters = list(node.children[0])
        val block = block(node.children[1])
        return concat(listOf(token(node.tokens[0]), text(" "), token(node.tokens[1]), parameters, hardline(), block))
    }
    fun postfix(node: SyntaxNode): Document = when (node.kind) {
        "call" -> list(node.children[1])
        "index" -> concat(listOf(token(node.tokens[0]), expression(node.children[1], 0), token(node.tokens[1])))
        "member" -> concat(listOf(token(node.tokens[0]), token(node.tokens[1])))
        else -> error("invalid postfix")
    }
    fun expression(original: SyntaxNode, required: Int): Document {
        val node = open(original, required)
        return when (node.kind) {
            "atom" -> token(node.tokens[0])
            "paren" -> concat(listOf(token(node.tokens[0]), expression(node.children[0], 0), token(node.tokens[1])))
            "unary" -> concat(listOf(token(node.tokens[0]), expression(node.children[0], 8)))
            "binary" -> {
                val p = level(node)
                var current = node
                val entries = mutableListOf<Pair<Int, SyntaxNode>>()
                while (current.kind == "binary" && level(current) == p) {
                    entries.add(Pair(current.tokens[0], current.children[1])); current = open(current.children[0], p)
                }
                val head = expression(current, p)
                val rest = mutableListOf<Document>()
                for ((op, right) in entries.asReversed()) rest.addAll(listOf(operatorLine(), token(op), space(), expression(right, p + 1)))
                group(concat(listOf(head, nest(profile.number("indent"), concat(rest)))))
            }
            "conditional" -> {
                val head = expression(node.children[0], 1)
                var current = node
                val rest = mutableListOf<Document>()
                while (true) {
                    rest.addAll(listOf(operatorLine(), token(current.tokens[0]), space(), expression(current.children[1], 0), operatorLine(), token(current.tokens[1]), space()))
                    val next = open(current.children[2], 0)
                    if (next.kind == "conditional") {
                        rest.add(expression(next.children[0], 1)); current = next
                    } else {
                        rest.add(expression(next, 0)); break
                    }
                }
                group(concat(listOf(head, nest(profile.number("indent"), concat(rest)))))
            }
            "call", "index", "member" -> {
                var current = node
                val operations = mutableListOf<SyntaxNode>()
                while (current.kind in listOf("call", "index", "member")) {
                    operations.add(current); current = open(current.children[0], 8)
                }
                val segments = mutableListOf(mutableListOf<SyntaxNode>())
                for (operation in operations.asReversed()) {
                    if (operation.kind == "member") segments.add(mutableListOf()); segments.last().add(operation)
                }
                val calls = segments.indices.drop(1).filter {
                    i -> segments[i].any {
                        it.kind == "call"
                    }
                }
                val parts = mutableListOf(expression(current, 8))
                if (calls.size < 2) {
                    for (operation in segments.flatten()) parts.add(postfix(operation)); concat(parts)
                }
                else {
                    val first = calls[0]
                    for (operation in segments.take(first).flatten()) parts.add(postfix(operation))
                    val rest = mutableListOf<Document>()
                    for (segment in segments.drop(first)) {
                        rest.add(softline()); for (operation in segment) rest.add(postfix(operation))
                    }
                    parts.add(nest(profile.number("indent"), concat(rest))); group(concat(parts))
                }
            }
            else -> error("invalid expression")
        }
    }
}
data class Formatted(val lines: List<String>, val firstFunction: Pair<String, Document>?, val modes: Map<Int, String>, val comments: Int)
fun formatSource(lines: List<String>, profile: Profile): Formatted {
    val (tokens, commentCount) = attach(Lexer.lex(lines))
    val items = Parser.parse(tokens)
    checkComments(items, tokens)
    val empty = items.isEmpty() && tokens.last().leading.isEmpty()
    val builder = Construction(tokens, profile)
    val parts = mutableListOf<Document>()
    var firstFunction: Pair<String, Document>? = null
    for ((i, node) in items.withIndex()) {
        if (i > 0) parts.add(builder.separator(builder.preblank(node.start)))
        val document = if (node.kind == "function") builder.function(node) else builder.declaration(node)
        if (node.kind == "function" && firstFunction == null) firstFunction = Pair(builder.tokens[node.tokens[1]].text, document)
        parts.add(document)
    }
    val closing = builder.tokens.last().leading
    if (closing.isNotEmpty()) {
        if (items.isNotEmpty()) parts.add(builder.separator(closing[0].blank)); parts.add(builder.comments(closing, null))
    }
    if (empty) return Formatted(emptyList(), firstFunction, emptyMap(), commentCount)
    val printed = Printer.print(concat(parts), profile.number("width"), profile.number("comment_column"))
    return Formatted(printed.lines, firstFunction, printed.modes, commentCount)
}
data class Source(val header: String, val name: String, val profile: String, val lines: MutableList<String> = mutableListOf())
fun inputs(): Pair<Map<String, Profile>, List<Source>> {
    val profiles = mutableMapOf<String, Profile>()
    var current = ""
    for (line in File("input/style.txt").readLines()) {
        if (line.isEmpty()) continue
        if (line.startsWith("[")) {
            current = line.substring(1, line.length - 1); profiles[current] = Profile()
        }
        else {
            val pair = line.split("=", limit = 2); profiles.getValue(current).values[pair[0]] = pair[1]
        }
    }
    val sources = mutableListOf<Source>()
    for (line in File("input/sources.txt").readLines()) {
        if (line.startsWith("=== ")) {
            val parts = line.split(" "); sources.add(Source(line, parts[1], parts[2]))
        } else sources.last().lines.add(line)
    }
    return Pair(profiles, sources)
}
fun write(name: String, lines: List<String>) {
    File("output").mkdirs()
    File("output/$name").writeText(if (lines.isEmpty()) "" else lines.joinToString("\n") + "\n")
}
fun main() {
    val (profiles, sources) = inputs()
    val formatted = mutableListOf<String>()
    val idempotency = mutableListOf<String>()
    val diagnostics = mutableListOf<String>()
    val docTree = mutableListOf<String>()
    val changes = mutableListOf<String>()
    for (source in sources) {
        val profile = profiles.getValue(source.profile)
        val original = source.lines.map {
            Lexer.trim(it)
        }
        formatted.add(source.header); docTree.add("=== ${source.name}"); changes.add("=== ${source.name}")
        try {
            val first = formatSource(source.lines, profile)
            formatted.addAll(first.lines)
            try {
                val second = formatSource(first.lines, profile)
                if (first.lines == second.lines) idempotency.add("${source.name}: stable")
                else {
                    val index = first.lines.zip(second.lines).indexOfFirst {
                        it.first != it.second
                    }.let {
                        if (it < 0) minOf(first.lines.size, second.lines.size) else it
                    }; idempotency.add("${source.name}: unstable at line ${index + 1}")
                }
            } catch (error: SourceError) {
                idempotency.add("${source.name}: unstable (second pass: ${error.line}:${error.column}: ${error.reason})")
            }
            val width = profile.number("width")
            for ((i, line) in first.lines.withIndex()) if (line.length > width) diagnostics.add("${source.name}:${i + 1}: warning: line too long (${line.length} > $width)")
            val longest = first.lines.maxOfOrNull {
                it.length
            } ?: 0
            val broken = first.modes.values.count {
                it != "flat"
            }
            val forced = first.modes.values.count {
                it == "forced"
            }
            docTree.add("metrics lines=${first.lines.size} longest=$longest comments=${first.comments} groups=${first.modes.size} broken=$broken forced=$forced")
            val function = first.firstFunction
            if (function == null) docTree.add("no function") else {
                docTree.add("function ${function.first}"); Report.tree(function.second, 0, first.modes, docTree)
            }
            changes.addAll(Report.diff(original, first.lines))
        } catch (error: SourceError) {
            formatted.addAll(original); idempotency.add("${source.name}: skipped (syntax error)")
            diagnostics.add("${source.name}:${error.line}:${error.column}: error: ${error.reason}")
            docTree.add("syntax error"); changes.add("skipped (syntax error)")
        }
    }
    if (diagnostics.isEmpty()) diagnostics.add("no diagnostics")
    write("formatted.txt", formatted); write("idempotency.txt", idempotency); write("diagnostics.txt", diagnostics); write("doc_tree.txt", docTree); write("changes.txt", changes)
}

data class SyntaxNode(val kind: String, val tokens: List<Int>, val children: List<SyntaxNode>, val start: Int, val end: Int, var trailing: Int? = null)
class Parser(val tokens: List<Token>) {
    var index = 0
    val peek: Token get() = tokens[index]
    val text: String get() = peek.text
    fun take(): Int = index++
    fun failure(expected: String): SourceError = SourceError(peek.line, peek.column, "expected $expected, found ${if (peek.kind == "end") "end of file" else "'$text'"}")
    fun symbol(value: String): Int {
        if (text != value) throw failure("'$value'"); return take()
    }
    fun identifier(): Int {
        if (peek.kind != "identifier") throw failure("identifier"); return take()
    }
    fun readType(): Int {
        if (!isType(text)) throw failure("type"); return take()
    }
    fun node(kind: String, tokens: List<Int>, children: List<SyntaxNode>, start: Int): SyntaxNode = SyntaxNode(kind, tokens, children, start, maxOf(0, index - 1))
    fun empty(): SyntaxNode = SyntaxNode("empty", emptyList(), emptyList(), index, index)
    fun list(kind: String, open: String, close: String, trailing: Boolean): SyntaxNode {
        val start = index
        val tokens = mutableListOf(symbol(open))
        val children = mutableListOf<SyntaxNode>()
        var tail: Int? = null
        if (text != close) {
            children.add(listElement(kind))
            while (text == ",") {
                val comma = take()
                if (trailing && text == close) {
                    tail = comma; break
                }
                tokens.add(comma); children.add(listElement(kind))
            }
        }
        tokens.add(symbol(close))
        return node(kind, tokens, children, start).copy(trailing = tail)
    }
    fun listElement(kind: String): SyntaxNode {
        if (kind == "params") {
            val start = index
            val tokens = listOf(readType(), identifier())
            val children = mutableListOf<SyntaxNode>()
            while (text == "[") {
                val s = index; val pair = listOf(take(), symbol("]")); children.add(node("dimension", pair, emptyList(), s))
            }
            return node("parameter", tokens, children, start)
        }
        return if (kind == "initlist") initializer() else expression()
    }
    fun initializer(): SyntaxNode = if (text == "{") list("initlist", "{", "}", true) else expression()
    fun declaration(semicolon: Boolean): SyntaxNode {
        val start = index; return declarationRest(start, listOf(readType(), identifier()), semicolon)
    }
    fun declarationRest(start: Int, original: List<Int>, semicolon: Boolean): SyntaxNode {
        val tokens = original.toMutableList()
        val children = mutableListOf<SyntaxNode>()
        while (text == "[") {
            val s = index
            val open = take()
            val content = if (text == "]") emptyList() else listOf(expression())
            val close = symbol("]")
            children.add(node("dimension", listOf(open, close), content, s))
        }
        if (text == "=") {
            tokens.add(take()); children.add(initializer())
        }
        if (semicolon) tokens.add(symbol(";"))
        return node("decl", tokens, children, start)
    }
    fun item(): SyntaxNode {
        val start = index
        val tokens = listOf(readType(), identifier())
        return if (text == "(") {
            val parameters = list("params", "(", ")", false); val block = this.block(); node("function", tokens, listOf(parameters, block), start)
        } else declarationRest(start, tokens, true)
    }
    fun block(): SyntaxNode {
        val start = index
        val open = symbol("{")
        val statements = mutableListOf<SyntaxNode>()
        while (text != "}" && peek.kind != "end") statements.add(statement())
        val close = symbol("}")
        return node("block", listOf(open, close), statements, start)
    }
    fun statement(): SyntaxNode {
        val start = index
        if (text == "{") return block()
        if (isType(text)) return declaration(true)
        return when (text) {
            "if", "while" -> {
                val kind = text
                val keyword = take(); val open = symbol("("); val condition = expression(); val close = symbol(")"); val body = statement()
                val tokens = mutableListOf(keyword, open, close)
                val children = mutableListOf(condition, body)
                if (kind == "if" && text == "else") {
                    tokens.add(take()); children.add(statement())
                }
                node(kind, tokens, children, start)
            }
            "for" -> {
                val keyword = take(); val open = symbol("(")
                val initial = if (text == ";") empty() else if (isType(text)) declaration(false) else simple()
                val first = symbol(";"); val condition = if (text == ";") empty() else expression(); val second = symbol(";")
                val update = if (text == ")") empty() else simple(); val close = symbol(")"); val body = statement()
                node("for", listOf(keyword, open, first, second, close), listOf(initial, condition, update, body), start)
            }
            "switch" -> {
                val keyword = take(); val open = symbol("("); val condition = expression(); val close = symbol(")"); val left = symbol("{")
                val children = mutableListOf(condition)
                while (text in listOf("case", "default")) {
                    val s = index; val label = take(); val kind = tokens[label].text
                    val body = mutableListOf<SyntaxNode>()
                    if (kind == "case") body.add(expression())
                    val colon = symbol(":")
                    while (text !in listOf("case", "default", "}") && peek.kind != "end") body.add(statement())
                    children.add(node(kind, listOf(label, colon), body, s))
                }
                val right = symbol("}")
                node("switch", listOf(keyword, open, close, left, right), children, start)
            }
            "return" -> {
                val keyword = take(); val children = if (text == ";") emptyList() else listOf(expression()); val semi = symbol(";"); node("return", listOf(keyword, semi), children, start)
            }
            "break", "continue" -> {
                val keyword = take(); val kind = tokens[keyword].text; val semi = symbol(";"); node(kind, listOf(keyword, semi), emptyList(), start)
            }
            else -> {
                val expression = simple(); val semi = symbol(";"); node("statement", listOf(semi), listOf(expression), start)
            }
        }
    }
    fun simple(): SyntaxNode {
        val start = index
        val left = expression()
        return if (text in listOf("=", "+=", "-=", "*=", "/=", "%=")) {
            val op = take(); val right = expression(); node("assign", listOf(op), listOf(left, right), start)
        } else node("exprstmt", emptyList(), listOf(left), start)
    }
    fun expression(): SyntaxNode {
        val start = index
        val condition = binary(1)
        return if (text == "?") {
            val question = take(); val yes = expression(); val colon = symbol(":"); val no = expression(); node("conditional", listOf(question, colon), listOf(condition, yes, no), start)
        } else condition
    }
    fun binary(precedence: Int): SyntaxNode {
        val start = index
        var left = if (precedence == 6) unary() else binary(precedence + 1)
        while (Parser.precedence(text) == precedence) {
            val op = take()
            val right = if (precedence == 6) unary() else binary(precedence + 1)
            left = node("binary", listOf(op), listOf(left, right), start)
        }
        return left
    }
    fun unary(): SyntaxNode {
        val start = index
        if (text in listOf("-", "!")) {
            val op = take(); val child = unary(); return node("unary", listOf(op), listOf(child), start)
        }
        var target = primary()
        while (true) {
            target = when (text) {
                "(" -> {
                    val args = list("args", "(", ")", false); node("call", emptyList(), listOf(target, args), start)
                }
                "[" -> {
                    val open = take(); val expression = expression(); val close = symbol("]"); node("index", listOf(open, close), listOf(target, expression), start)
                }
                "." -> {
                    val dot = take(); val name = identifier(); node("member", listOf(dot, name), listOf(target), start)
                }
                else -> return target
            }
        }
    }
    fun primary(): SyntaxNode {
        val start = index
        if (peek.kind in listOf("identifier", "number", "string") || text in listOf("true", "false")) return node("atom", listOf(take()), emptyList(), start)
        if (text == "(") {
            val open = take(); val child = expression(); val close = symbol(")"); return node("paren", listOf(open, close), listOf(child), start)
        }
        throw failure("expression")
    }
    companion object {
        fun isType(text: String): Boolean = text in listOf("int", "float", "bool", "string", "void")
        fun precedence(text: String): Int = when (text) {
            "||" -> 1; "&&" -> 2; "==", "!=" -> 3; "<", "<=", ">", ">=" -> 4; "+", "-" -> 5; "*", "/", "%" -> 6; else -> 0
        }
        fun parse(tokens: List<Token>): List<SyntaxNode> {
            val parser = Parser(tokens)
            val items = mutableListOf<SyntaxNode>()
            while (parser.peek.kind != "end") items.add(parser.item())
            return items
        }
    }
}

data class Command(val indent: Int, val flat: Boolean, val document: Document)
data class Printed(val lines: List<String>, val modes: Map<Int, String>)
object Printer {
    fun fits(width: Int, first: Command, stack: List<Command>): Boolean {
        if (width < 0) return false
        var remaining = width
        val check = (stack + first).toMutableList()
        while (check.isNotEmpty()) {
            val (i, flat, document) = check.removeAt(check.lastIndex)
            when (document) {
                is Document.Text -> remaining -= document.value.length
                is Document.IfBreak -> remaining -= if (flat) document.flat.length else document.broken.length
                Document.Line -> if (flat) remaining-- else return true
                Document.Softline -> if (!flat) return true
                Document.Hardline -> return true
                is Document.Concat -> for (part in document.children.reversed()) check.add(Command(i, flat, part))
                is Document.Group -> check.add(Command(i, if (document.forced()) false else flat, document.child))
                is Document.Nest -> check.add(Command(i, flat, document.child))
                is Document.Align -> check.add(Command(i, flat, document.child))
                else -> Unit
            }
            if (remaining < 0) return false
        }
        return true
    }
    fun print(document: Document, width: Int, column: Int): Printed {
        val stack = mutableListOf(Command(0, false, document))
        val lines = mutableListOf<String>()
        val modes = mutableMapOf<Int, String>()
        var current = ""
        var col = 0
        val pending = mutableListOf<String>()
        fun finalizeLine() {
            var line = Lexer.trim(current)
            if (pending.isNotEmpty()) {
                val comment = pending.joinToString(" ")
                line += if (column > 0 && line.length < column - 1 && column - 1 + comment.length <= width) " ".repeat(column - 1 - line.length) else " "
                line += comment; pending.clear()
            }
            lines.add(line)
        }
        while (stack.isNotEmpty()) {
            val (i, flat, doc) = stack.removeAt(stack.lastIndex)
            when (doc) {
                is Document.Text -> {
                    current += doc.value; col += doc.value.length
                }
                is Document.IfBreak -> {
                    val value = if (flat) doc.flat else doc.broken; current += value; col += value.length
                }
                Document.Line, Document.Softline, Document.Hardline -> {
                    val newline = doc == Document.Hardline || !flat
                    if (newline) {
                        finalizeLine(); current = " ".repeat(i); col = i
                    }
                    else if (doc == Document.Line) {
                        current += " "; col++
                    }
                }
                is Document.Concat -> for (part in doc.children.reversed()) stack.add(Command(i, flat, part))
                is Document.Nest -> stack.add(Command(i + doc.amount, flat, doc.child))
                is Document.Align -> stack.add(Command(col, flat, doc.child))
                is Document.Suffix -> pending.add(doc.value)
                Document.BreakParent -> Unit
                is Document.Group -> {
                    val mode = if (flat) "flat" else if (doc.forced()) "forced" else if (fits(width - col, Command(i, true, doc.child), stack)) "flat" else "break"
                    modes[doc.id] = mode; stack.add(Command(i, mode == "flat", doc.child))
                }
            }
        }
        finalizeLine()
        return Printed(lines, modes)
    }
}

object Report {
    fun tree(document: Document, depth: Int, modes: Map<Int, String>, out: MutableList<String>) {
        val prefix = " ".repeat(depth * 2)
        when (document) {
            is Document.Concat -> for (part in document.children) tree(part, depth, modes, out)
            is Document.Text -> out.add(prefix + "text \"${document.value}\"")
            is Document.Suffix -> out.add(prefix + "suffix \"${document.value}\"")
            is Document.IfBreak -> out.add(prefix + "if_break \"${document.broken}\" \"${document.flat}\"")
            is Document.Group -> {
                out.add(prefix + "group ${modes.getValue(document.id)}"); tree(document.child, depth + 1, modes, out)
            }
            is Document.Nest -> {
                out.add(prefix + "nest ${document.amount}"); tree(document.child, depth + 1, modes, out)
            }
            is Document.Align -> {
                out.add(prefix + "align"); tree(document.child, depth + 1, modes, out)
            }
            Document.Line -> out.add(prefix + "line")
            Document.Softline -> out.add(prefix + "softline")
            Document.Hardline -> out.add(prefix + "hardline")
            Document.BreakParent -> out.add(prefix + "break_parent")
        }
    }
    fun diff(a: List<String>, b: List<String>): List<String> {
        val n = a.size
        val m = b.size
        val lcs = Array(n + 1) {
            IntArray(m + 1)
        }
        for (i in n - 1 downTo 0) for (j in m - 1 downTo 0) lcs[i][j] = if (a[i] == b[j]) lcs[i + 1][j + 1] + 1 else maxOf(lcs[i + 1][j], lcs[i][j + 1])
        var i = 0
        var j = 0
        var deleted = 0
        var inserted = 0
        val hunks = mutableListOf<List<String>>()
        while (i < n || j < m) {
            if (i < n && j < m && a[i] == b[j]) {
                i++; j++; continue
            }
            val i0 = i
            val j0 = j
            var d = 0
            var e = 0
            val lines = mutableListOf<String>()
            while (i < n || j < m) {
                if (i < n && j < m && a[i] == b[j]) break
                if (j == m || i < n && lcs[i + 1][j] >= lcs[i][j + 1]) {
                    lines.add("-" + a[i]); i++; d++
                } else {
                    lines.add("+" + b[j]); j++; e++
                }
            }
            deleted += d; inserted += e
            hunks.add(listOf("@@ -${if (d > 0) i0 + 1 else i0},$d +${if (e > 0) j0 + 1 else j0},$e @@") + lines)
        }
        return listOf("hunks=${hunks.size} deleted=$deleted inserted=$inserted") + hunks.flatten()
    }
}
